import React from "react";
import Operator from "./Operator";
import FractionDisplay from "./FractionDisplay";
import Parentheses from "./Parentheses";
import FractionInput from "./FractionInput";

const CompoundFraction = ({
  leftNumerator,
  leftDenominator,
  operator,
  rightNumber,
  rightNumerator,
  rightDenominator,
  inputHandlers,
  mathInputNull,
  setMathInputNull,
}) => {
  return (
    <div className="flex flex-col pl-2 md:pl-0">
      {/* Part 1 - Static display */}
      <div className="flex flex-col md:flex-row">
        <div className="part-1 md:pt-[6px]">
          <table className="digit">
            <tr>
              <td className="flex flex-row items-center">
                <FractionDisplay
                  numerator={leftNumerator}
                  denominator={leftDenominator}
                />
                <Operator symbol={operator} className="mx-3 md:mx-6" />
                <table className="3rd col mr-1 md:mr-2">
                  <tbody>
                    <tr>
                      <td>{rightNumber}</td>
                    </tr>
                  </tbody>
                </table>
                <FractionDisplay
                  numerator={rightNumerator}
                  denominator={rightDenominator}
                />
                <Operator symbol="=" className="mx-3 md:mx-6" />
              </td>
            </tr>
          </table>
        </div>

        {/* Part 2 - Input section */}
        <div className="part-2 flex flex-row mt-8 md:mt-0">
          <Operator
            symbol="="
            className="mr-2 md:mr-4 flex items-center md:hidden"
          />
          <table className="digit">
            <tr>
              <td className="flex flex-row items-center">
                <FractionDisplay
                  numerator={leftNumerator}
                  denominator={leftDenominator}
                />
                <Operator symbol={operator} className="mx-2 md:mx-4" />
                <Parentheses type="(" className="mr-2 md:mr-4 h-[100px]" />
                <FractionInput
                  numeratorValue={inputHandlers.numerator1}
                  denominatorValue={inputHandlers.denominator1}
                  onNumeratorChange={(e) =>
                    inputHandlers.setNumerator1(e.target.value)
                  }
                  onDenominatorChange={(e) =>
                    inputHandlers.setDenominator1(e.target.value)
                  }
                />
                <Operator symbol="+" className="mx-2 md:mx-4" />
                <FractionInput
                  numeratorValue={inputHandlers.numerator2}
                  denominatorValue={inputHandlers.denominator2}
                  onNumeratorChange={(e) =>
                    inputHandlers.setNumerator2(e.target.value)
                  }
                  onDenominatorChange={(e) =>
                    inputHandlers.setDenominator2(e.target.value)
                  }
                />
                <Parentheses type=")" className="ml-2 md:ml-4 h-[100px]" />
                <Operator symbol="=" className="mx-3 md:mx-6" />
              </td>
            </tr>
          </table>
        </div>
      </div>

      {/* Bottom row */}
      <div className="bottom-row mt-8 md:mt-16">
        <table className="digit">
          <tr>
            <td className="flex flex-row items-center">
              <Operator symbol="=" className="mr-3 md:mr-6" />
              <FractionDisplay
                numerator={leftNumerator}
                denominator={leftDenominator}
              />
              <Operator symbol={operator} className="mx-3 md:mx-6" />
              <FractionInput
                numeratorValue={inputHandlers.numerator3}
                denominatorValue={inputHandlers.denominator3}
                onNumeratorChange={(e) =>
                  inputHandlers.setNumerator3(e.target.value)
                }
                onDenominatorChange={(e) =>
                  inputHandlers.setDenominator3(e.target.value)
                }
              />
              <Operator symbol="=" className="mx-2 md:mx-4" />
              <FractionInput
                numeratorValue={inputHandlers.inputsNum}
                denominatorValue={inputHandlers.inputsDenom}
                onNumeratorChange={(e) =>
                  inputHandlers.setInputsNum(e.target.value)
                }
                onDenominatorChange={(e) =>
                  inputHandlers.setInputsDenom(e.target.value)
                }
              />
            </td>
          </tr>
        </table>
      </div>
    </div>
  );
};

export default CompoundFraction;
